style.css:
@-moz-document domain("youtube.com") {
html, body {
    background: url("https://i.imgur.com/qjvFwR5.png") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  ytd-app {
    background-color: transparent !important;
  }

  #guide, ytd-mini-guide-renderer, ytd-masthead, tp-yt-app-drawer, ytd-rich-grid-renderer {
    background-color: rgba(0, 0, 0, 0.6) !important;
    backdrop-filter: blur(8px);
  }

  ytd-rich-grid-media, ytd-video-renderer {
    background-color: rgba(0, 0, 0, 0.4) !important;
    border-radius: 10px;
    margin-bottom: 10px;
  }

  ::-webkit-scrollbar-thumb {
    background: #8e44ad !important;
  }

  ::-webkit-scrollbar {
    width: 8px;
    background: rgba(0, 0, 0, 0.3);
  }
}
